function covered(){
  try{
    if(!document.elementFromPoint)return false;
    var mr2=modal.getBoundingClientRect?modal.getBoundingClientRect():null;
    if(!mr2||!mr2.width||!mr2.height)return false;
    var cx=Math.round(mr2.left+mr2.width/2);
    var cy=Math.round(mr2.top+Math.min(mr2.height/2,80));
    if(cx<0||cy<0||cx>(window.innerWidth||0)||cy>(window.innerHeight||0))return false;
    var el=document.elementFromPoint(cx,cy);
    if(!el)return false;
    var n=el,g=0;
    while(n&&g++<30){if(n===root||n===modal)return false;n=n.parentNode;}
    return true;
  }catch(eC){return false;}
}
function raise(){
  try{
    UI._pvSet(root,{'z-index':'2147483647'});
    var host=document.documentElement||document.body;
    if(host&&host.appendChild)host.appendChild(root);
    LOG.warn('[MS] 预览层被其它元素遮挡，已提升到最高层并重挂到 documentElement');
  }catch(eR){}
}
function heal(){
  try{
    if(!root.parentNode)return;
    if(covered())raise();
    var rr=root.getBoundingClientRect?root.getBoundingClientRect():null;
    var mr=modal.getBoundingClientRect?modal.getBoundingClientRect():null;
    if(rr&&(rr.width<80||rr.height<80)){
      LOG.warn('[MS] 预览遮罩尺寸异常，强制铺满视口:',rr.width,'x',rr.height);
      UI._pvSet(root,{position:'fixed',left:'0',top:'0',right:'0',bottom:'0',width:'100%',height:'100%',display:'flex','align-items':(_isMobP?'flex-end':'center'),'justify-content':'center',padding:'0'});
      UI._pvSet(modal,{position:'relative',margin:'0 auto',display:'block'});
    }
    if(mr&&(mr.width<120||mr.height<90)){
      LOG.warn('[MS] 预览弹窗尺寸异常，强制尺寸:',mr.width,'x',mr.height);
      UI._pvSet(modal,{width:W+'px','max-width':W+'px','min-height':'220px','height':'auto','border-radius':(_isMobP?'16px 16px 0 0':'16px'),display:'block'});
      if(kind==='video'||kind==='m3u8'||kind==='img')setRatio(0.5625);
    }
  }catch(eHeal){}
}
