UI._dlVlinks=function(list,cb){
  var total=list?list.length:0,okN=0,errN=0,doneN=0,idx=0,running=0,CONC=3;
  if(!total){if(cb)cb(0,0,0,0);return;}
  function report(){try{if(cb)cb(okN,errN,doneN,total);}catch(eC0){}}
  function one(u,fin){
    var d=UI._vlinkResolved[u];
    var go=function(real){
      try{Dl.one(real,Dl.buildName(u,1,'',State.config.nameTpl),State.config.batchRetry,State.config.customHeaders);okN++;}
      catch(eD){errN++;}
      doneN++;report();fin();
    };
    if(d&&(d.videoUrl||(d.videoUrls&&d.videoUrls[0]))){go(d.videoUrl||d.videoUrls[0]);return;}
    try{
      Resolver.resolve(u,function(data,err){
        if(data&&(data.videoUrl||(data.videoUrls&&data.videoUrls[0]))){UI._vlinkResolved[u]=data;go(data.videoUrl||data.videoUrls[0]);}
        else{errN++;doneN++;report();fin();}
      });
    }catch(eR){errN++;doneN++;report();fin();}
  }
  function pump(){
    while(running<CONC&&idx<total){
      running++;
      one(list[idx++],function(){
        running--;
        if(doneN>=total){toast('页面链接下载完成：成功 '+okN+'，失败 '+errN,errN?'#f59e0b':'#10b981');}
        else setTimeout(pump,0);
      });
    }
  }
  report();
  pump();
};
